# Twin of t191: x^3 = 1 iff the order of x is 1 or 3 (order divides 3, and 3 is prime).
# Brute force over the cyclic groups Z/m (m <= 60) and the symmetric group S4.
from itertools import permutations
def divisors(n):
    return [d for d in range(1, n + 1) if n % d == 0]
ok = divisors(3) == [1, 3]
for m in range(1, 61):
    for x in range(m):
        order = next(k for k in range(1, m + 1) if (k * x) % m == 0)
        ok &= (((3 * x) % m == 0) == (order in (1, 3)))
def comp(p, q):
    return tuple(p[q[i]] for i in range(len(q)))
e = tuple(range(4))
for p in permutations(range(4)):
    k, q = 1, p
    while q != e:
        q, k = comp(q, p), k + 1
    cube = comp(p, comp(p, p))
    ok &= ((cube == e) == (k in (1, 3)))
print(ok)

# Twin of t211: every group of order 80 has a normal Sylow p-subgroup for some prime p dividing 80.
# Sylow counts: n_p divides 80 / p^a and n_p = 1 mod p. If n_5 = 16 and n_2 = 5, the 16 subgroups of
# order 5 give 16 * 4 = 64 elements of order 5, and two distinct Sylow 2-subgroups (order 16) give at
# least 16 + 1 more elements, so 64 + 17 = 81 > 80: impossible. Hence n_5 = 1 or n_2 = 1.
n = 80
def factor(n):
    f, p = {}, 2
    while p * p <= n:
        while n % p == 0:
            f[p] = f.get(p, 0) + 1
            n //= p
        p += 1
    if n > 1:
        f[n] = f.get(n, 0) + 1
    return f
f = factor(n)
assert f == {2: 4, 5: 1}
counts = {p: [d for d in range(1, n // p**a + 1) if (n // p**a) % d == 0 and d % p == 1] for p, a in f.items()}
assert counts == {2: [1, 5], 5: [1, 16]}
n5, n2 = 16, 5
elements_order5 = n5 * (5 - 1)
elements_2power_at_least = 16 + 1
print(elements_order5 + elements_2power_at_least > n)
